mapper.select:
select 


order by ea.sort_order, ea.area_code, ei.sort_order, ei.item_code, ee.evaluation_year desc, ee.sort_order, ee.element_code
limit #{criteria.safeSize} offset #{criteria.offset}

select version_status
from evaluation_rule_versions
where rule_version_id = #{ruleVersionId}

select ei.item_id
from evaluation_items ei
inner join evaluation_areas ea on ea.area_id = ei.area_id
where ea.rule_version_id = #{ruleVersionId}
  and ea.area_code = #{areaCode}
  and ei.item_code = #{itemCode}

select 

where ee.item_id = #{itemId}
  and ee.evaluation_year = #{evaluationYear}
  and ee.element_code = #{elementCode}
